def test_pytest_ignore_collect_markexpr_branches(
    pytestconfig: pytest.Config,
    monkeypatch: pytest.MonkeyPatch,
    markexpr: str,
    expected: bool | None,
) -> None:
    """Verify pytest_ignore_collect skips tests/docs when -m excludes docs and defers otherwise."""
