def test_docs_helpers_boundary_cases(tmp_path: Path) -> None:
    """Verify excluded_doc_names, materialize_markdown_text, and resolve_markdown_sources boundary paths."""
    assert excluded_doc_names(tmp_path / "missing_zensical.toml") == set()

    non_macro_fm = "---\ntitle: Plain Page\nrender_macros: false\n---\n# Plain\n"
    assert materialize_markdown_text(non_macro_fm) == non_macro_fm

    scalar_fm = "---\n- item\n---\n# Scalar Front Matter\n"
    assert materialize_markdown_text(scalar_fm) == scalar_fm

    nested_md = tmp_path / "docs" / "guide.md"
    nested_md.parent.mkdir(parents=True)
    nested_md.write_text("# Guide\n", encoding="utf-8")
    assert resolve_markdown_sources([nested_md], repo_root=tmp_path) == [("docs/guide.md", "# Guide\n")]
